function profileData = importRoughnessProfile(filename, dataLines)
%-------------------------------------------------------------------------
%                     importRoughnessProfile function                                                                        
%-------------------------------------------------------------------------
% FUNCTION DESCRIPTION:
% importRoughnessProfile function is a Matlab autogenerated function that 
% reads data from text file filename for the default selection, returnsing
% the data as a table.
%
% INPUTS:
%   filename  - file name
%   dataLines - row interval(s) of text file filename
%
% OUTPUTS:
%   profileData - profile data in a tabular format
%
%-------------------------------------------------------------------------
% Copyright (c) 2026, Diego Díaz Salamanca                           
% Contact: diazsdiego@uniovi.es                                      
%-------------------------------------------------------------------------

%% Input handling

% If dataLines is not specified, define defaults
if nargin < 2
    dataLines = [1, Inf];
end

%% Set up the Import Options and import the data
opts = delimitedTextImportOptions("NumVariables", 2);

% Specify range and delimiter
opts.DataLines = dataLines;
opts.Delimiter = "\t";

% Specify column names and types
opts.VariableNames = ["X", "Y"];
opts.VariableTypes = ["double", "double"];

% Specify file level properties
opts.ExtraColumnsRule = "ignore";
opts.EmptyLineRule = "read";

% Import the data
profileData = readtable(filename, opts);

end
